import { test, expect } from '@playwright/test'
import { mkdirSync, readFileSync } from 'node:fs'
import { join } from 'node:path'

/**
 * The sketch's reference photo (TODO/sketch-003), driven against `/` — the running app.
 *
 * - **Trace to scale** (sketch-001's case 10, steps 1, 2 and 7): load
 *   `e2e/fixtures/trace-bracket.jpg` (generated by `scripts/generate-trace-fixtures.mjs`,
 *   5 px per mm, the ruler's 0 mark at image px (200, 915) and its 100 mm mark at
 *   (700, 915)), Set scale along 100 mm of the ruler, Done, reload, Edit sketch — the photo
 *   is still there at the calibrated scale.
 * - **Hostile project load** (case 11): `e2e/fixtures/hostile-images.ndjson` through File ▸
 *   Open — the same parse-and-load path a hosted or `#/gist/` document takes — drops each bad
 *   image with its own warning, renders every sketch, opens no dialog, and sends **no request
 *   off the app's origin**.
 *
 * Real input throughout (`page.mouse`, trusted touch), never a `PointerEvent` dispatched at
 * the canvas: the photo must not intercept a press (ui-020 finding #1), and only real input
 * goes through the browser's own hit-testing. Every viewport and every engine: canvas,
 * WebGL textures, a worker decode and persistence are all in play.
 */

const SNAPSHOT_DIR = join(process.cwd(), 'test-results', 'reference-image-snapshots')
const BRACKET = join(process.cwd(), 'e2e', 'fixtures', 'trace-bracket.jpg')
const HOSTILE = join(process.cwd(), 'e2e', 'fixtures', 'hostile-images.ndjson')
const FOV_DEG = 45
/** The fixture's size, and where its ruler marks are, in image px. */
const IMAGE = { widthPx: 1400, heightPx: 1000 }
const RULER_0 = [200, 915]
const RULER_100MM = [700, 915]

/** @param {import('@playwright/test').TestInfo} info */
const isPhone = (info) => info.project.name.endsWith('-phone')

/** @param {import('@playwright/test').Page} page */
async function openLibrary(page) {
  const rows = page.getByTestId('library-rows')
  if (await rows.isVisible()) return
  await page.getByTestId('library-tab').click()
  await expect(rows).toBeVisible()
}

/** @param {import('@playwright/test').Page} page */
async function openNewSketch(page) {
  await openLibrary(page)
  const row = await page.getByTestId('library-row-primitive.sketch').boundingBox()
  const view = await page.getByTestId('viewport').boundingBox()
  if (!row || !view) throw new Error('no Sketch row or viewport')
  await page.mouse.move(row.x + row.width / 2, row.y + row.height / 2)
  await page.mouse.down()
  await page.mouse.move(view.x + view.width / 2, view.y + view.height * 0.4 - 30, { steps: 8 })
  await page.mouse.move(view.x + view.width / 2, view.y + view.height * 0.4, { steps: 4 })
  await page.mouse.up()
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-sketch-mode', 'true')
}

/**
 * The sketch origin on screen and pixels per mm, while the editor looks straight down.
 *
 * @param {import('@playwright/test').Page} page
 */
async function sketchScreen(page) {
  const view = page.getByTestId('viewport')
  const box = await view.boundingBox()
  if (!box) throw new Error('no viewport')
  const distanceMm = Number(await view.getAttribute('data-camera-distance'))
  const mmPerPx = (2 * distanceMm * Math.tan((FOV_DEG * Math.PI) / 360)) / box.height
  return { cx: box.x + box.width / 2, cy: box.y + box.height / 2, pxPerMm: 1 / mmPerPx }
}

/**
 * Where an image pixel is on screen, for an unrotated photo centred at `offsetMm`.
 *
 * @param {import('@playwright/test').Page} page
 * @param {readonly number[]} px
 * @param {number} mmPerPx
 * @param {readonly number[]} [offsetMm]
 */
async function imagePxOnScreen(page, px, mmPerPx, offsetMm = [0, 0]) {
  const { cx, cy, pxPerMm } = await sketchScreen(page)
  const xMm = offsetMm[0] + (px[0] - IMAGE.widthPx / 2) * mmPerPx
  const yMm = offsetMm[1] - (px[1] - IMAGE.heightPx / 2) * mmPerPx
  return { x: cx + xMm * pxPerMm, y: cy - yMm * pxPerMm }
}

/** @param {import('@playwright/test').Page} page */
async function openSlices(page) {
  if ((await page.getByTestId('sketch-slices-panel').count()) === 0) await page.getByTestId('sketch-slices-toggle').click()
  await expect(page.getByTestId('sketch-slices-panel')).toBeVisible()
}

/** @param {import('@playwright/test').Page} page */
async function closePanel(page) {
  if ((await page.getByTestId('sketch-panel-sheet').count()) > 0) await page.getByTestId('sketch-panel-close').click()
}

/** @param {import('@playwright/test').Page} page */
async function addBracketPhoto(page) {
  await openSlices(page)
  await expect(page.getByTestId('sketch-image-add')).toHaveText(/Add image/)
  await page.getByTestId('sketch-image-input').setInputFiles(BRACKET)
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-reference-image', 'shown')
  await expect(page.getByTestId('sketch-image-badge')).toHaveText('Not to scale')
  await expect(page.getByTestId('sketch-slice-image-badge-0')).toHaveText('Not to scale')
  await expect(page.getByTestId('sketch-image-add')).toHaveText(/Replace image/)
}

/**
 * A real mouse drag between two client points.
 *
 * @param {import('@playwright/test').Page} page
 * @param {{ x: number, y: number }} from
 * @param {{ x: number, y: number }} to
 */
async function mouseDrag(page, from, to) {
  await page.mouse.move(from.x, from.y)
  await page.mouse.down()
  await page.mouse.move((from.x + to.x) / 2, from.y + 2, { steps: 6 })
  await page.mouse.move(to.x, to.y, { steps: 6 })
  await page.mouse.up()
}

/** @param {import('@playwright/test').Page} page */
async function scaleLineEnds(page) {
  const line = page.getByTestId('sketch-scale-line').locator('line').nth(1)
  return {
    x1: Number(await line.getAttribute('x1')),
    y1: Number(await line.getAttribute('y1')),
    x2: Number(await line.getAttribute('x2')),
    y2: Number(await line.getAttribute('y2')),
  }
}

/**
 * Select a body from the Inspector's object list and open **Edit sketch** on it.
 *
 * @param {import('@playwright/test').Page} page
 * @param {string} id
 */
async function editSketch(page, id) {
  const list = page.getByTestId('object-list')
  const inspector = page.getByTestId('inspector')
  if (!(await list.isVisible())) {
    if ((await inspector.getAttribute('data-open')) !== 'true' && (await page.getByTestId('inspector-tab').isVisible())) {
      await page.getByTestId('inspector-tab').click()
    }
    if (!(await list.isVisible())) await page.getByTestId('inspector-objects-header').click()
  }
  await page.getByTestId(`objects-row-${id}`).click()
  await expect(inspector).toHaveAttribute('data-selected-id', id)
  if (await page.getByTestId('inspector-edit-sketch').isHidden()) await page.getByTestId('inspector-tab').click()
  await page.getByTestId('inspector-edit-sketch').click()
}

/**
 * The scale a badge shows, as a number: `1 px = 0.199 mm` → 0.199. The line is placed by hand
 * on screen, and at a phone's zoom one screen pixel spans several image pixels — so a real
 * calibration lands within a pixel's worth of 0.2, and the assertion allows for that.
 *
 * @param {import('@playwright/test').Locator} badge
 */
async function expectScaleNear(badge, mmPerPx = 0.2) {
  await expect(badge).toHaveText(/^1 px = 0\.\d+ mm$/)
  await expect.poll(async () => Math.abs(Number(/= ([\d.]+) mm/.exec((await badge.textContent()) ?? '')?.[1]) / mmPerPx - 1)).toBeLessThan(0.02)
}

test.beforeEach(async ({ page }) => {
  await page.goto('/')
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-webgl', 'ready')
})

test('trace to scale: load the photo, Set scale along 100 mm of its ruler, Done, reload, Edit sketch — still to scale', async ({ page }, info) => {
  await openNewSketch(page)
  await addBracketPhoto(page)
  await expect(page.getByTestId('sketch-image-corner-badge')).toHaveText('Not to scale')

  // Set scale: the sheet folds to its header, the banner takes the toolbar's slot.
  await page.getByTestId('sketch-image-scale').click()
  await expect(page.getByTestId('sketch-scale-tool')).toHaveAttribute('data-step', 'first')
  await expect(page.getByTestId('sketch-panel-sheet')).toHaveAttribute('data-collapsed', 'true')
  await expect(page.getByTestId('sketch-toolbar')).toHaveCount(0)

  // Press on the ruler's 0 mark and drag to its 100 mm mark (provisional 0.1 mm per px).
  const zero = await imagePxOnScreen(page, RULER_0, 0.1)
  const hundred = await imagePxOnScreen(page, RULER_100MM, 0.1)
  await mouseDrag(page, zero, hundred)
  await expect(page.getByTestId('sketch-scale-tool')).toHaveAttribute('data-step', 'length')
  await page.getByTestId('sketch-scale-length').fill('100')
  await page.getByTestId('sketch-scale-unit').selectOption('mm')
  mkdirSync(SNAPSHOT_DIR, { recursive: true })
  await page.screenshot({ path: join(SNAPSHOT_DIR, `${info.project.name}-set-scale.png`) })
  await page.getByTestId('sketch-scale-apply').click()

  // The badge reads the real scale; the line stays drawn in dimension style, labelled as typed,
  // and the photo rescaled about the line's first point — the 0 mark did not move on screen.
  await expect(page.getByTestId('sketch-scale-tool')).toHaveCount(0)
  await expectScaleNear(page.getByTestId('sketch-image-badge'))
  await expectScaleNear(page.getByTestId('sketch-slice-image-badge-0'))
  await expectScaleNear(page.getByTestId('sketch-image-corner-badge'))
  await expect(page.getByTestId('sketch-scale-line-label')).toHaveText('100 mm')
  const ends = await scaleLineEnds(page)
  const box = await page.getByTestId('viewport').boundingBox()
  expect(Math.abs(ends.x1 + (box?.x ?? 0) - zero.x)).toBeLessThan(3)
  expect(Math.abs(ends.y1 + (box?.y ?? 0) - zero.y)).toBeLessThan(3)
  // …and the line now spans 100 mm on the sketch: twice as long on screen as before.
  const { pxPerMm } = await sketchScreen(page)
  expect(Math.hypot(ends.x2 - ends.x1, ends.y2 - ends.y1) / pxPerMm).toBeCloseTo(100, -0.5)

  // The photo never intercepts a press: a circle drawn starting right on it draws.
  await closePanel(page)
  await page.getByTestId('sketch-tool-circle').click()
  const { cx, cy } = await sketchScreen(page)
  await mouseDrag(page, { x: cx, y: cy }, { x: cx + 12 * pxPerMm, y: cy })
  await expect(page.getByTestId('sketch-strokes')).toHaveAttribute('data-path-count', '1')
  await page.screenshot({ path: join(SNAPSHOT_DIR, `${info.project.name}-calibrated.png`) })
  await page.getByTestId('sketch-done').click()
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-body-count', '1')
  // Outside the editor the photo is hidden: it is a tracing aid, not part of the scene.
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-reference-image', 'none')
  await expect(page.getByTestId('undo-button')).toHaveAttribute('title', /Place Sketch 1/)

  // Save (autosave), reload, Edit sketch: the photo and its scale came back from the project.
  await expect(page.getByTestId('save-status')).toContainText('Saved', { timeout: 15000 })
  await page.reload()
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-body-count', '1')
  const id = /** @type {string} */ (await page.locator('[data-testid="scene-bodies"] li').first().getAttribute('data-body-id'))
  await editSketch(page, id)
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-sketch-mode', 'true')
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-reference-image', 'shown')
  await openSlices(page)
  await expectScaleNear(page.getByTestId('sketch-image-badge'))
  await expect(page.getByTestId('sketch-scale-line-label')).toHaveText('100 mm')
  await page.screenshot({ path: join(SNAPSHOT_DIR, `${info.project.name}-reopened.png`) })
  await page.getByTestId('sketch-cancel').click()
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-reference-image', 'none')
})

test('desktop only: Set scale by two clicks; outlines traced first are rescaled on Yes; one Undo takes the sketch and its photo', async ({ page }, info) => {
  test.skip(info.project.name.endsWith('-phone') || info.project.name.endsWith('-tablet'), 'the touch pass below covers the narrow viewports')
  await openNewSketch(page)
  // Trace first: a 10 mm circle at the origin, while the photo is still "1 px = 0.1 mm".
  await page.getByTestId('sketch-tool-circle').click()
  const { cx, cy, pxPerMm } = await sketchScreen(page)
  await page.keyboard.down('Shift')
  await mouseDrag(page, { x: cx, y: cy }, { x: cx + 10 * pxPerMm, y: cy })
  await page.keyboard.up('Shift')
  await addBracketPhoto(page)

  await page.getByTestId('sketch-image-scale').click()
  const zero = await imagePxOnScreen(page, RULER_0, 0.1)
  const ten = await imagePxOnScreen(page, RULER_100MM, 0.1)
  await page.mouse.click(zero.x, zero.y)
  await expect(page.getByTestId('sketch-scale-tool')).toHaveAttribute('data-step', 'second')
  await page.mouse.move(ten.x - 30, ten.y, { steps: 4 }) // the line's free end follows the mouse
  await expect(page.getByTestId('sketch-scale-line')).toBeVisible()
  await page.mouse.click(ten.x, ten.y)
  await page.getByTestId('sketch-scale-length').fill('10')
  await page.getByTestId('sketch-scale-unit').selectOption('cm')
  await page.getByTestId('sketch-scale-apply').click()
  await expect(page.getByTestId('sketch-scale-confirm-text')).toHaveText('Rescale the 1 outline on this slice to match the image?')
  await expect(page.getByTestId('sketch-scale-rescale-yes')).toBeFocused() // Yes is the default
  await page.keyboard.press('Enter')
  await expectScaleNear(page.getByTestId('sketch-image-badge'))

  // The circle doubled with the photo: pick it and read it back.
  await closePanel(page)
  await page.getByTestId('sketch-tool-select').click()
  const after = await sketchScreen(page)
  // The circle scaled about the 0 mark, so find its new centre: (0,0) → 2 × (0 − (−50), 0 − (−41.5)) + (−50, −41.5).
  const centre = { x: after.cx + 50 * after.pxPerMm, y: after.cy - 41.5 * after.pxPerMm }
  await page.mouse.click(centre.x + 3, centre.y + 3)
  await expect(page.getByTestId('sketch-selection-status')).toContainText(/Circle, Solid — (19|20|21)(\.\d+)? mm radius/)

  await page.getByTestId('sketch-done').click()
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-body-count', '1')
  await page.getByTestId('undo-button').click()
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-body-count', '0')
  await expect(page.getByTestId('undo-button')).toBeDisabled() // sketch and photo were one step
  await page.getByTestId('redo-button').click()
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-body-count', '1')
})

test('desktop only: Esc stands Set scale down; Remove image takes the photo off; Cancel forgets it', async ({ page }, info) => {
  test.skip(!info.project.name.endsWith('-laptop'), 'keyboard path')
  await openNewSketch(page)
  await addBracketPhoto(page)
  await page.getByTestId('sketch-image-opacity').fill('80')
  await expect(page.getByTestId('sketch-image-opacity')).toHaveValue('80')
  await page.getByTestId('sketch-image-x').fill('12')
  await page.getByTestId('sketch-image-x').press('Enter')
  await page.getByTestId('sketch-image-scale').click()
  await expect(page.getByTestId('sketch-scale-tool')).toBeVisible()
  await page.keyboard.press('Escape')
  await expect(page.getByTestId('sketch-scale-tool')).toHaveCount(0)
  await expect(page.getByTestId('sketch-toolbar')).toBeVisible()
  await page.getByTestId('sketch-image-remove').click()
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-reference-image', 'none')
  await expect(page.getByTestId('sketch-image-add')).toHaveText(/Add image/)
  await addBracketPhoto(page)
  await page.getByTestId('sketch-cancel').click()
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-body-count', '0')
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-reference-image', 'none')
})

test('touch only: Set scale by two finger taps on a phone, no modifier, the sheet out of the way', async ({ page, browserName }, info) => {
  test.skip(!isPhone(info), 'phone touch pass')
  test.skip(browserName === 'firefox', 'Firefox has no touch emulation')
  await openNewSketch(page)
  await addBracketPhoto(page)
  await page.getByTestId('sketch-image-scale').tap()
  await expect(page.getByTestId('sketch-panel-sheet')).toHaveAttribute('data-collapsed', 'true')
  // The banner's Cancel is a full-size touch target.
  const cancel = await page.getByTestId('sketch-scale-cancel').boundingBox()
  expect(Math.min(cancel?.width ?? 0, cancel?.height ?? 0)).toBeGreaterThanOrEqual(43.5)
  const zero = await imagePxOnScreen(page, RULER_0, 0.1)
  const hundred = await imagePxOnScreen(page, RULER_100MM, 0.1)
  await page.touchscreen.tap(zero.x, zero.y)
  await expect(page.getByTestId('sketch-scale-tool')).toHaveAttribute('data-step', 'second')
  await page.touchscreen.tap(hundred.x, hundred.y)
  await expect(page.getByTestId('sketch-scale-tool')).toHaveAttribute('data-step', 'length')
  await page.getByTestId('sketch-scale-length').fill('100')
  await page.getByTestId('sketch-scale-apply').tap()
  await expectScaleNear(page.getByTestId('sketch-image-badge'))
  await page.screenshot({ path: join(SNAPSHOT_DIR, `${info.project.name}-touch-scaled.png`) })
})

test('hostile project: four bad images are each dropped with a warning; every sketch renders; no dialog; nothing leaves the origin', async ({ page }, info) => {
  const origin = new URL(page.url()).origin
  /** @type {string[]} */
  const offOrigin = []
  page.on('request', (request) => {
    const url = request.url()
    if (url.startsWith('data:') || url.startsWith('blob:')) return
    if (new URL(url).origin !== origin) offOrigin.push(url)
  })
  let dialogs = 0
  page.on('dialog', async (dialog) => {
    dialogs += 1
    await dialog.dismiss()
  })
  // The `<input type=file>` path on every engine (save-load-ui.e2e.js's FORCE_FALLBACK).
  await page.addInitScript(() => {
    Object.defineProperty(window, 'showOpenFilePicker', { value: undefined, configurable: true })
  })
  await page.reload()
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-webgl', 'ready')
  await page.getByTestId('file-menu-button').click()
  const chooserEvent = page.waitForEvent('filechooser')
  await page.getByTestId('file-open').click()
  const chooser = await chooserEvent
  await chooser.setFiles({ name: 'hostile.ndjson', mimeType: 'text/plain', buffer: readFileSync(HOSTILE) })

  await expect(page.getByTestId('viewport')).toHaveAttribute('data-body-count', '4')
  const status = page.getByTestId('save-status')
  await expect(status).toContainText('Opened hostile.ndjson, but')
  const text = (await status.textContent()) ?? ''
  for (const id of ['img-5f9000000000000000000001', 'img-5f9000000000000000000002', 'img-5f9000000000000000000003', 'img-5f9000000000000000000004']) {
    expect(text.split(id).length - 1).toBe(1) // one warning per bad image
  }
  expect(text).toContain("reference image removed — it couldn't be verified as a safe image")
  expect(text).toContain('image/svg+xml is not allowed')
  expect(text).toContain('unexpected field "url"')
  expect(text).toContain('declared as image/jpeg')
  expect(text).toContain('50000 × 50000')

  // Edit one: its geometry loads, and its Slices row says the photo was removed.
  const id = /** @type {string} */ (await page.locator('[data-testid="scene-bodies"] li').first().getAttribute('data-body-id'))
  await editSketch(page, id)
  await expect(page.getByTestId('viewport')).toHaveAttribute('data-reference-image', 'removed')
  await openSlices(page)
  await expect(page.getByTestId('sketch-image-removed')).toHaveText("Reference image removed — it couldn't be verified as a safe image")
  await expect(page.getByTestId('sketch-slice-image-removed-0')).toBeVisible()
  mkdirSync(SNAPSHOT_DIR, { recursive: true })
  await page.screenshot({ path: join(SNAPSHOT_DIR, `${info.project.name}-hostile.png`) })
  await page.getByTestId('sketch-cancel').click()

  expect(dialogs).toBe(0)
  expect(offOrigin).toEqual([])
})
